<?php require_once __DIR__.'/../includes/functions.php';need_role(['petugas']);$s=db()->prepare('SELECT COUNT(*) FROM reports WHERE id_petugas=?');$s->execute([me()['id_user']]);$total=(int)$s->fetchColumn();$byStatus=db()->prepare('SELECT status,COUNT(*) total FROM reports WHERE id_petugas=? GROUP BY status');$byStatus->execute([me()['id_user']]);$statusCounts=[];foreach($byStatus->fetchAll() as $sc)$statusCounts[$sc['status']]=(int)$sc['total'];$q=db()->prepare('SELECT id_laporan,nomor_laporan,judul,status,created_at FROM reports WHERE id_petugas=? ORDER BY updated_at DESC LIMIT 10');$q->execute([me()['id_user']]);$rows=$q->fetchAll();header_page('Dashboard Petugas');?><h1>Dashboard petugas</h1><div class="stats"><div class="stat"><b><?=$total?></b><span>Laporan ditugaskan</span></div><?php foreach(status_options() as $st):?><div class="stat"><b><?=$statusCounts[$st]??0?></b><span><?=e($st)?></span></div><?php endforeach;?></div><p><a class="btn" href="daftar_laporan.php">Daftar laporan</a> <a class="btn outline" href="profil.php">Profil</a></p><div class="table-wrap"><table><thead><tr><th>Nomor</th><th>Judul</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nomor_laporan'])?></td><td><?=e($r['judul'])?></td><td><?=status_badge($r['status'])?></td><td><a href="detail_laporan.php?id=<?=$r['id_laporan']?>">Tangani</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty">Belum ada laporan yang ditugaskan kepada Anda.</div><?php endif;?><?php footer_page();?>